// =============================================================================
// rag-lib.js — Funciones puras de [BS] Pregunta libre (RAG). Sin dependencias,
// probadas en local con scripts/test-rag-lib.js y copiadas a los nodos Code
// por scripts/build-pregunta.js (mismo patrón que scripts/chunker.js).
// =============================================================================

const TELEGRAM_MAX = 4096;
const PART_LIMIT = 3900; // margen para el footer de fuentes y el HTML añadido

// Sintaxis de Bootstrap 4 que ya no existe (o cambió) en 5.3. Se busca solo
// dentro de bloques de código: en el texto explicativo el LLM puede nombrar
// "ml-3" para decir justamente que es de v4 (regla 3 del prompt).
const V4_PATTERNS = [
  /\bml-\d\b/, /\bmr-\d\b/, /\bpl-\d\b/, /\bpr-\d\b/,
  /\bml-auto\b/, /\bmr-auto\b/,
  /data-toggle=/, /data-target=/, /data-dismiss=/,
  /\bfloat-left\b/, /\bfloat-right\b/,
  /\bbadge-pill\b/, /\bform-group\b/, /\bcustom-select\b/,
  /\bcustom-control\b/, /\bjumbotron\b/,
  /\bmedia-body\b/,
];

// -----------------------------------------------------------------------------
// buildContext: arma el bloque de fragmentos numerados que se le pega al LLM
// (turno de usuario, después del systemInstruction de prompts/rag.md).
// chunks = filas de rag/02_buscar.sql, en el orden en que se van a citar.
// -----------------------------------------------------------------------------
// question = lo que escribió el usuario; searchQuery = la consulta con la que
// se buscó (traducida al inglés y/o con el "eso" resuelto por el historial).
// Si son distintas, el LLM ve las dos: la original conserva la intención, la
// de búsqueda resuelve las referencias.
function buildContext(chunks, question, searchQuery = question) {
  const fragmentos = chunks
    .map((c, i) => `[${i + 1}] (${headingText(c)})\n${c.content}`)
    .join('\n\n---\n\n');
  const pregunta = searchQuery && searchQuery !== question
    ? `${question}\n(Consulta usada para buscar en la documentación: ${searchQuery})`
    : question;
  return `Fragmentos recuperados:\n\n${fragmentos}\n\nPregunta del usuario:\n${pregunta}`;
}

function headingText(c) {
  return Array.isArray(c.heading_path) ? c.heading_path.join(' > ') : String(c.heading_path ?? '');
}

// -----------------------------------------------------------------------------
// Lectura de la respuesta del LLM, sea Gemini (generateContent) u OpenAI
// (chat/completions): la cadena de modelos usa los dos y "Procesar respuesta"
// no debería saber cuál contestó.
// Gemini Flash "piensa": puede traer partes de pensamiento (thought: true) que
// no son texto para el usuario, y esos tokens se cobran aparte
// (thoughtsTokenCount). En OpenAI, los tokens de razonamiento ya vienen dentro
// de completion_tokens.
// -----------------------------------------------------------------------------
function llmText(response) {
  if (response?.choices) return String(response.choices[0]?.message?.content ?? '').trim();
  const parts = response?.candidates?.[0]?.content?.parts || [];
  return parts.filter((p) => !p.thought && typeof p.text === 'string').map((p) => p.text).join('').trim();
}

function llmTokens(response) {
  if (response?.usage) {
    return { prompt: response.usage.prompt_tokens ?? 0, completion: response.usage.completion_tokens ?? 0 };
  }
  const u = response?.usageMetadata || {};
  return {
    prompt: u.promptTokenCount ?? 0,
    completion: (u.candidatesTokenCount ?? 0) + (u.thoughtsTokenCount ?? 0),
  };
}

// -----------------------------------------------------------------------------
// Frase fija de "fuera de la documentación" (regla 6 de prompts/rag.md). Si el
// LLM responde con ella, el código lo trata como no_context: sin citas ni
// lista de fuentes, aunque el modelo haya puesto alguna.
// -----------------------------------------------------------------------------
const NOT_IN_DOCS = 'Esto no está en la documentación de Bootstrap 5.3.';

function isNotInDocs(text) {
  const norm = (s) => String(s).toLowerCase().replace(/[“”"«»*]/g, '').trim();
  return norm(text).startsWith(norm(NOT_IN_DOCS).replace(/\.$/, ''));
}

// Resultado de "Reescribir consulta": IGUAL (o vacío, o algo raro) = usar la
// pregunta original tal cual. Así el modelo no puede agregar palabras a una
// pregunta que ya se entendía sola (ver prompts/rag-reescribir.md).
function rewriteResult(text, original) {
  const line = String(text ?? '').split('\n')[0].replace(/^["'«“]|["'»”]$/g, '').trim();
  if (!line || /^igual\.?$/i.test(line) || line.length > 300) return original;
  return line;
}

// Por qué terminó sin texto (para el mensaje de error y el registro).
function llmFinishReason(response) {
  return response?.choices?.[0]?.finish_reason ?? response?.candidates?.[0]?.finishReason ?? 'desconocido';
}

function escapeHtml(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Inverso de lo anterior para el envío de respaldo en texto plano (cuando
// Telegram rechaza el HTML): quitar solo las etiquetas dejaría "&lt;div&gt;"
// a la vista. &amp; va al final para no des-escapar dos veces.
function htmlToPlain(html) {
  return String(html).replace(/<[^>]+>/g, '')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
}

// -----------------------------------------------------------------------------
// extractCitations: números [n] citados en el markdown, en orden de aparición,
// sin repetir. Sirve para el fallback (el LLM no citó nada) y para depurar.
// -----------------------------------------------------------------------------
// Los modelos a veces agrupan citas ("[2, 3, 4]") aunque el prompt pida una
// por corchete. Se normalizan a "[2][3][4]" antes de todo lo demás, fuera de
// los bloques de código (ahí un "[1, 2]" es un arreglo de JavaScript).
function normalizeCitations(markdown) {
  return String(markdown).split(/(```[\s\S]*?```)/g).map((seg) => seg.startsWith('```')
    ? seg
    : seg.replace(/\[(\d+(?:\s*,\s*\d+)+)\]/g, (_, list) => [...new Set(list.split(',').map((n) => n.trim()))].map((n) => `[${n}]`).join(''))
  ).join('');
}

function extractCitations(markdown, chunkCount) {
  const seen = new Set();
  const out = [];
  const re = /\[(\d+)\]/g;
  let m;
  while ((m = re.exec(markdown))) {
    const n = Number(m[1]);
    if (n >= 1 && n <= chunkCount && !seen.has(n)) { seen.add(n); out.push(n); }
  }
  return out;
}

// -----------------------------------------------------------------------------
// buildSourcesFooter: bloque final "📚 Fuentes" en Markdown (se convierte a
// HTML junto con el resto). chunks[n-1] da la URL y el heading de la cita n.
// -----------------------------------------------------------------------------
function buildSourcesFooter(citedNumbers, chunks) {
  if (!citedNumbers.length) return '';
  const lines = citedNumbers.map((n) => {
    const c = chunks[n - 1];
    const heading = Array.isArray(c.heading_path) ? c.heading_path[c.heading_path.length - 1] : headingText(c);
    return `[${n}] ${heading}: ${c.url}`;
  });
  return `\n\n📚 Fuentes\n${lines.join('\n')}`;
}

// -----------------------------------------------------------------------------
// findV4Syntax: sintaxis de Bootstrap 4 dentro de bloques ```code```. Devuelve
// la lista de coincidencias (para loguear/reintentar), vacía si no hay nada.
// -----------------------------------------------------------------------------
function findV4Syntax(markdown) {
  const found = [];
  const re = /```[\w-]*\n([\s\S]*?)```/g;
  let m;
  while ((m = re.exec(markdown))) {
    const code = m[1];
    for (const p of V4_PATTERNS) {
      const hit = code.match(p);
      if (hit) found.push(hit[0]);
    }
  }
  return [...new Set(found)];
}

// -----------------------------------------------------------------------------
// splitMarkdown: divide en partes ≤ PART_LIMIT caracteres, cortando solo entre
// bloques (líneas en blanco), nunca a mitad de un ``` ... ``` ni de una cita
// [n] (que siempre es corta, así que cae entera en un lado u otro igual).
// -----------------------------------------------------------------------------
function splitMarkdown(markdown, limit = PART_LIMIT) {
  if (markdown.length <= limit) return [markdown];

  // Bloques = párrafos y bloques de código completos, separados por \n\n.
  const blocks = [];
  const re = /```[\w-]*\n[\s\S]*?```|[^\n]+(?:\n(?!\n)[^\n]+)*/g;
  let m;
  let lastIndex = 0;
  while ((m = re.exec(markdown))) {
    blocks.push(m[0]);
    lastIndex = re.lastIndex;
  }
  if (lastIndex < markdown.length) blocks.push(markdown.slice(lastIndex).trim());

  const parts = [];
  let cur = '';
  for (const block of blocks) {
    const candidate = cur ? `${cur}\n\n${block}` : block;
    if (candidate.length > limit && cur) {
      parts.push(cur);
      cur = block;
    } else if (candidate.length > limit) {
      // un solo bloque más grande que el límite: corte duro por líneas.
      let rest = block;
      while (rest.length > limit) {
        parts.push(rest.slice(0, limit));
        rest = rest.slice(limit);
      }
      cur = rest;
    } else {
      cur = candidate;
    }
  }
  if (cur) parts.push(cur);
  return parts;
}

// -----------------------------------------------------------------------------
// markdownToTelegramHtml: subconjunto de Markdown -> HTML permitido por
// Telegram (b, code, pre, a). Todo lo demás se escapa. citationMap: número
// de cita -> URL (o null si es inválida, en cuyo caso se borra la cita).
// -----------------------------------------------------------------------------
function markdownToTelegramHtml(markdown, citationMap = {}) {
  let out = '';
  const fenceRe = /```([\w-]*)\n([\s\S]*?)```/g;
  let last = 0;
  let m;
  while ((m = fenceRe.exec(markdown))) {
    out += convertInline(markdown.slice(last, m.index), citationMap);
    const lang = m[1];
    const code = escapeHtml(m[2].replace(/\n$/, ''));
    out += lang
      ? `<pre><code class="language-${escapeHtml(lang)}">${code}</code></pre>`
      : `<pre>${code}</pre>`;
    last = fenceRe.lastIndex;
  }
  out += convertInline(markdown.slice(last), citationMap);
  return out.trim();
}

// El código en línea se separa primero: negrita y citas se aplican solo fuera
// de él. Telegram no admite etiquetas dentro de <code>, y un `[1]` o `**x**`
// dentro de código es literal.
function convertInline(text, citationMap) {
  return escapeHtml(text)
    .split('\n')
    .map((line) => {
      const l = line.replace(/^(\s*)[-*]\s+/, '$1• ');
      return l.split(/(`[^`\n]+`)/g).map((seg) => {
        if (/^`[^`]+`$/.test(seg)) return `<code>${seg.slice(1, -1)}</code>`;
        return seg
          .replace(/\*\*(.+?)\*\*/g, '<b>$1</b>')
          // cursiva *texto*: el asterisco no puede ir pegado a un espacio por
          // dentro, para no tocar un "5 * 3" suelto.
          .replace(/(^|[^\w*])\*(?!\s)([^*\n]+?)(?<!\s)\*(?![\w*])/g, '$1<i>$2</i>')
          .replace(/ ?\[(\d+)\]/g, (full, n) => {
            const url = citationMap[Number(n)];
            return url ? `${full.startsWith(' ') ? ' ' : ''}<a href="${escapeHtml(url)}">[${n}]</a>` : '';
          });
      }).join('');
    })
    .join('\n');
}

// -----------------------------------------------------------------------------
// formatAnswer: junta todo lo anterior. chunks = filas de rag/02_buscar.sql en
// el mismo orden usado en buildContext. Devuelve { parts, citedUrls } listo
// para enviar (una llamada sendMessage por parte, en orden).
// -----------------------------------------------------------------------------
function formatAnswer(rawMarkdown, chunks) {
  const markdown = normalizeCitations(rawMarkdown);
  const cited = extractCitations(markdown, chunks.length);
  // Si el LLM no citó nada, se usan los 2 fragmentos más similares (ya vienen
  // ordenados por similarity desc desde rag/02_buscar.sql) para cumplir la
  // regla de "citar siempre".
  const citedOrFallback = cited.length ? cited : chunks.slice(0, 2).map((_, i) => i + 1);

  const citationMap = {};
  for (const n of citedOrFallback) citationMap[n] = chunks[n - 1]?.url || null;

  const footer = buildSourcesFooter(citedOrFallback, chunks);
  const full = markdown + footer;

  const mdParts = splitMarkdown(full, PART_LIMIT);
  const parts = mdParts.map((p) => markdownToTelegramHtml(p, citationMap)).filter((p) => p.length);

  const citedUrls = [...new Set(citedOrFallback.map((n) => chunks[n - 1]?.url).filter(Boolean))];
  return { parts, citedUrls };
}

// Guardado así (y no `module.exports = …` a secas) porque este archivo se
// copia entero dentro de los nodos Code de n8n (mismo patrón que chunker.js):
// ahí no existe `module`, y sin el guard lanzaría ReferenceError.
if (typeof module !== 'undefined') module.exports = {
  TELEGRAM_MAX, PART_LIMIT, V4_PATTERNS,
  NOT_IN_DOCS, isNotInDocs, rewriteResult,
  buildContext, llmText, llmTokens, llmFinishReason, escapeHtml, htmlToPlain, normalizeCitations, extractCitations,
  buildSourcesFooter, findV4Syntax, splitMarkdown, markdownToTelegramHtml,
  convertInline, formatAnswer,
};

// =============================================================================
// estudio-lib.js — Funciones puras de la Fase 5: [BS] Lección del día,
// [BS] Progreso y [BS] Envío diario. Probadas con scripts/test-estudio-lib.js
// y copiadas a los nodos Code por scripts/build-estudio.js.
//
// Reutiliza rag-lib.js (markdown → HTML de Telegram y el detector de sintaxis
// de Bootstrap 4). En Node se importa; en n8n el build pega rag-lib.js ANTES de
// este archivo, así que sus funciones ya existen como globales.
// =============================================================================

const ragLib = typeof findV4Syntax === 'function'
  ? { markdownToTelegramHtml, findV4Syntax, escapeHtml }
  : require('./rag-lib');

// Cuánto de la página ve el modelo para escribir la lección. Las páginas
// grandes (Navbar, Spacing) pasan de 40 000 caracteres; los primeros
// fragmentos son la introducción y el uso básico, que es lo que va en una
// lección. ~20 000 caracteres ≈ 5 000 tokens ≈ US$ 0,004 por tema, una vez.
const LESSON_SOURCE_CHARS = 20000;
const LESSON_MAX_CHARS = 2600;   // el prompt pide 2200; margen antes de rechazar
const LESSON_SECTIONS = ['Lo esencial', 'Ejemplo', 'Para recordar'];

const SECTION_LABEL = {
  'getting-started': 'Getting started', layout: 'Layout', content: 'Content', forms: 'Forms',
  components: 'Components', helpers: 'Helpers', utilities: 'Utilities', customize: 'Customize',
};

// -----------------------------------------------------------------------------
// Entrada de [BS] Lección del día: del router (/hoy, /saltar, botones) o del
// envío diario ({ chat_id, text: '/hoy' }).
//   h:t:<order_index> → test     ("Ponerme a prueba")
//   h:s:<order_index> → saltar   ("Ya lo sé")
//   n:hoy             → hoy      ("Siguiente lección")
// -----------------------------------------------------------------------------
function parseLessonInput({ text, callback_data } = {}) {
  const cb = String(callback_data ?? '');
  let m = cb.match(/^h:([ts]):(\d{1,4})$/);
  if (m) return { action: m[1] === 't' ? 'test' : 'saltar', topic_order: Number(m[2]) };
  if (/^\/saltar\b/i.test(String(text ?? '').trim())) return { action: 'saltar', topic_order: null };
  return { action: 'hoy', topic_order: null };
}

// -----------------------------------------------------------------------------
// buildLessonPrompt: turno de usuario. errors = motivos del intento anterior.
// -----------------------------------------------------------------------------
function buildLessonPrompt({ title, section, chunks, errors = [] }) {
  const parts = [];
  let used = 0;
  for (const [i, c] of (chunks ?? []).entries()) {
    const heading = Array.isArray(c.heading_path) ? c.heading_path.join(' > ') : '';
    const block = `[${i + 1}] (${heading})\n${c.content}`;
    if (used && used + block.length > LESSON_SOURCE_CHARS) break;
    parts.push(block.slice(0, LESSON_SOURCE_CHARS));
    used += block.length;
  }
  const lines = [
    `Tema: ${title} (sección ${SECTION_LABEL[section] ?? section} de la documentación de Bootstrap 5.3)`,
    '',
    'Fragmentos de la página oficial, en orden:',
    '',
    parts.join('\n\n---\n\n'),
    '',
  ];
  if (errors.length) lines.push('Tu intento anterior fue rechazado por esto; corrígelo:', ...errors.map((e) => `- ${e}`), '');
  lines.push('Escribe la lección.');
  return lines.join('\n');
}

// -----------------------------------------------------------------------------
// validateLesson: lista de errores (vacía = válida), redactados para el modelo.
// lenient (último intento): el largo ya no rechaza si igual cabe en Telegram.
// -----------------------------------------------------------------------------
function validateLesson(markdown, { lenient = false } = {}) {
  const md = String(markdown ?? '').trim();
  const errors = [];
  if (!md) {
    errors.push('La respuesta vino vacía.');
    return errors;
  }
  const max = lenient ? 3400 : LESSON_MAX_CHARS;
  if (md.length > max) errors.push(`La lección tiene ${md.length} caracteres; el máximo es 2200. Acórtala.`);
  const missing = LESSON_SECTIONS.filter((s) => !md.includes(`**${s}**`));
  if (missing.length) errors.push(`Faltan las partes en negrita: ${missing.map((s) => `**${s}**`).join(', ')}.`);
  if (!/```[\w-]*\n[\s\S]*?```/.test(md)) errors.push('Falta el bloque de código del ejemplo.');
  // URLs solo fuera del código: dentro sí pueden ir (el <link> del CDN en Introduction).
  const prose = md.replace(/```[\w-]*\n[\s\S]*?```/g, '');
  if (/https?:\/\//i.test(prose)) errors.push('No incluyas URLs en el texto: el bot agrega el enlace oficial.');
  const v4 = ragLib.findV4Syntax(md);
  if (v4.length) errors.push(`El código tiene sintaxis de Bootstrap 4 (${v4.join(', ')}): usa solo 5.3.`);
  return errors;
}

// El modelo a veces envuelve todo en ```markdown … ```: se quita esa envoltura.
function cleanLesson(text) {
  return String(text ?? '').trim().replace(/^```(?:markdown|md)?\n([\s\S]*)\n```$/i, '$1').trim();
}

// -----------------------------------------------------------------------------
// formatLessonMessage: HTML del mensaje de /hoy. El enlace sale de study_path,
// nunca del modelo.
// -----------------------------------------------------------------------------
function formatLessonMessage({ title, url, section, order_index, total, markdown }) {
  const esc = ragLib.escapeHtml;
  const head = `📖 <b>Lección del día · ${esc(title)}</b>\n` +
    `<i>${esc(SECTION_LABEL[section] ?? section)} · tema ${Number(order_index) + 1} de ${total} de la ruta</i>`;
  const body = ragLib.markdownToTelegramHtml(markdown);
  const link = `🔗 <a href="${esc(url)}">Documentación oficial: ${esc(title)}</a>`;
  return `${head}\n\n${body}\n\n${link}\n\nCuando termines de leer, ponte a prueba: 3 preguntas, apruebas con 2.`;
}

function routeFinishedMessage(total) {
  return `🎉 <b>¡Terminaste la ruta!</b> Viste los ${total} temas de Bootstrap 5.3.\n\n` +
    'Sigue con /quiz: ahora te pregunta sobre todo de tus temas más débiles y de los repasos que vencen.';
}

function skipMessage({ saltado, siguiente }) {
  const esc = ragLib.escapeHtml;
  if (!saltado) return 'No hay tema que saltar: ya terminaste la ruta. 🎉';
  return `⏭️ Marqué <b>${esc(saltado)}</b> como visto.\n` +
    (siguiente ? `Lo siguiente en la ruta: <b>${esc(siguiente)}</b>.` : '¡Con eso terminaste la ruta! 🎉');
}

function reminderMessage(title) {
  return `⏰ Hoy todavía no hiciste el test de <b>${ragLib.escapeHtml(title)}</b>. ` +
    'Son 3 preguntas; con 2 aciertos pasas al siguiente tema.';
}

// -----------------------------------------------------------------------------
// /hora: "/hora 10 20" → horas; "/hora off" / "/hora on"; "/hora" → consultar.
// -----------------------------------------------------------------------------
function parseHoraCommand(text) {
  const arg = String(text ?? '').trim().replace(/^\/hora(@\w+)?/i, '').trim().toLowerCase();
  if (!arg) return { hours: null, enabled: null };
  if (/^(off|no|apagar|desactivar)$/.test(arg)) return { hours: null, enabled: false };
  if (/^(on|si|sí|activar)$/.test(arg)) return { hours: null, enabled: true };
  const nums = arg.split(/[\s,;y]+/).filter(Boolean);
  if (!nums.every((n) => /^\d{1,2}$/.test(n))) return { error: true };
  const hours = [...new Set(nums.map(Number))].sort((a, b) => a - b);
  if (!hours.length || hours.length > 4 || hours.some((h) => h > 23)) return { error: true };
  return { hours, enabled: true };
}

function formatHoraReply({ hours, enabled }, { error = false } = {}) {
  const usage = 'Uso: <code>/hora 10 20</code> (hasta 4 horas, de 0 a 23, hora de Lima), ' +
    '<code>/hora off</code> para apagar el envío diario y <code>/hora on</code> para encenderlo.';
  if (error) return `No entendí esas horas. ${usage}`;
  const fmt = (h) => `${String(h).padStart(2, '0')}:00`;
  const hs = (hours ?? []).map(Number);
  if (!enabled) return `🔕 Envío diario apagado. Tus horas guardadas: ${hs.map(fmt).join(' y ')}.\n\n${usage}`;
  const [first, ...rest] = hs;
  return `⏰ Envío diario: ${hs.map(fmt).join(' y ')} (hora de Lima).\n` +
    `• ${fmt(first)}: la lección de /hoy (antes, un repaso si tienes alguno vencido).\n` +
    (rest.length ? `• ${rest.map(fmt).join(', ')}: repaso, recordatorio del test o una pregunta de /quiz.\n` : '') +
    `\n${usage}`;
}

// -----------------------------------------------------------------------------
// /progreso: gráfico de QuickChart (Chart.js v2) y el texto que lo acompaña.
// -----------------------------------------------------------------------------
function buildProgressChart(secciones) {
  const rows = secciones ?? [];
  const pct = (a, b) => (Number(b) ? Math.round((100 * Number(a)) / Number(b)) : 0);
  return {
    type: 'horizontalBar',
    data: {
      labels: rows.map((s) => `${SECTION_LABEL[s.section] ?? s.section} (${s.vistos}/${s.temas})`),
      datasets: [
        { label: '% de temas vistos', backgroundColor: '#7952b3', data: rows.map((s) => pct(s.vistos, s.temas)) },
        { label: '% dominados', backgroundColor: '#20c997', data: rows.map((s) => pct(s.dominados, s.temas)) },
      ],
    },
    options: {
      title: { display: true, text: 'Avance en la ruta de Bootstrap 5.3', fontSize: 18 },
      legend: { position: 'bottom' },
      scales: { xAxes: [{ ticks: { min: 0, max: 100, stepSize: 25 } }] },
      plugins: { datalabels: { display: false } },
    },
  };
}

// Pie de foto de Telegram: máximo 1024 caracteres.
function formatProgressCaption(r) {
  const esc = ragLib.escapeHtml;
  const temas = (r.secciones ?? []).reduce((a, s) => a + Number(s.temas), 0);
  const vistos = (r.secciones ?? []).reduce((a, s) => a + Number(s.vistos), 0);
  const resp = Number(r.respondidas ?? 0);
  const acierto = resp ? Math.round((100 * Number(r.aciertos ?? 0)) / resp) : 0;
  const lines = [
    `📊 <b>Tu progreso</b>`,
    `Ruta: ${vistos} de ${temas} temas vistos.`,
    resp ? `Quiz: ${resp} respuestas, ${acierto} % de acierto.` : 'Quiz: todavía no respondiste preguntas.',
    r.actual ? `Tema actual: <b>${esc(r.actual)}</b> (/hoy).` : 'Ruta terminada 🎉',
  ];
  if (Number(r.vencidos)) lines.push(`🔁 Repasos pendientes: ${r.vencidos} (/quiz los prioriza).`);
  const deb = r.debiles ?? [];
  if (deb.length) {
    lines.push('', '<b>Temas más débiles</b>');
    deb.forEach((d, i) => lines.push(`${i + 1}. ${esc(d.title)}: ${d.tasa} % (${d.correct}/${Number(d.correct) + Number(d.wrong)})`));
  } else if (resp) {
    lines.push('', 'Sin temas débiles por ahora 💪');
  }
  return lines.join('\n').slice(0, 1024);
}

if (typeof module !== 'undefined') module.exports = {
  LESSON_SOURCE_CHARS, LESSON_MAX_CHARS, SECTION_LABEL,
  parseLessonInput, buildLessonPrompt, validateLesson, cleanLesson, formatLessonMessage,
  routeFinishedMessage, skipMessage, reminderMessage,
  parseHoraCommand, formatHoraReply, buildProgressChart, formatProgressCaption,
};


